    finalDecision_iterDone_next = iterDoneReg;
    finalDecision_rdCount_next = {3'b0, rdCountReg};
    dataO = finalDecision_dataOut;
    startO = finalDecision_startOut;
    endO = finalDecision_endOut;
    validO = finalDecision_validOut;
    finalDecision_startOut_next = finalDecision_startOut_temp;
    finalDecision_validOut_next = finalDecision_validOut_temp;
    finalDecision_countZ_next = finalDecision_countZ_temp;
    finalDecision_read_next = finalDecision_read_temp;
  end

  assign zeroData = 1'b0;

  assign dataTmp = (validO == 1'b0 ? zeroData :
              dataO);

  always @(posedge clk or posedge reset)
    begin : dataOut_process
      if (reset == 1'b1) begin
        dataOut_reg <= {2{1'b0}};
      end
      else begin
        if (enb) begin
          dataOut_reg[0] <= dataTmp;
          dataOut_reg[1] <= dataOut_reg[0];
        end
      end
    end

  assign data_2 = dataOut_reg[1];

  assign const1 = 1'b0;

  assign startTmp = (validO == 1'b0 ? const1 :
              startO);

  always @(posedge clk or posedge reset)
    begin : startOut_process
      if (reset == 1'b1) begin
        startOut_reg <= {2{1'b0}};
      end
      else begin
        if (enb) begin
          startOut_reg[0] <= startTmp;
          startOut_reg[1] <= startOut_reg[0];
        end
      end
    end

  assign start = startOut_reg[1];

  assign endTmp = (validO == 1'b0 ? const1 :
              endO);

  always @(posedge clk or posedge reset)
    begin : endOut_process
      if (reset == 1'b1) begin
        endOut_reg <= {2{1'b0}};
      end
      else begin
        if (enb) begin
          endOut_reg[0] <= endTmp;
          endOut_reg[1] <= endOut_reg[0];
        end
      end
    end

  assign end_rsvd = endOut_reg[1];

  assign validTmp = (validO == 1'b0 ? const1 :
              validO);

  always @(posedge clk or posedge reset)
    begin : validOut_process
      if (reset == 1'b1) begin
        validOut_reg <= {2{1'b0}};
      end
      else begin
        if (enb) begin
          validOut_reg[0] <= validTmp;
          validOut_reg[1] <= validOut_reg[0];
        end
      end
    end

  assign valid_2 = validOut_reg[1];

  assign const1_dtc = {7'b0, const1};

  assign constH = 1'b1;

  assign add_Comp_1 = {7'b0, constH};
  assign iterTmp = iterOut + add_Comp_1;

  assign iterOutReg = (termPass == 1'b0 ? iterOut :
              iterTmp);

  assign iterTmp_1 = (validO == 1'b0 ? const1_dtc :
              iterOutReg);

  always @(posedge clk or posedge reset)
    begin : actIter_1_process
      if (reset == 1'b1) begin
        for(actIter_t_1 = 32'sd0; actIter_t_1 <= 32'sd1; actIter_t_1 = actIter_t_1 + 32'sd1) begin
          actIter_reg[actIter_t_1] <= 8'b00000000;
        end
      end
      else begin
        if (enb) begin
          for(actIter_t_0_0 = 32'sd0; actIter_t_0_0 <= 32'sd1; actIter_t_0_0 = actIter_t_0_0 + 32'sd1) begin
            actIter_reg[actIter_t_0_0] <= actIter_reg_next[actIter_t_0_0];
          end
        end
      end
    end

  assign actIter = actIter_reg[1];
  assign actIter_reg_next[0] = iterTmp_1;
  assign actIter_reg_next[1] = actIter_reg[0];

  assign parCheckTmp = (validO == 1'b0 ? const1 :
              termPass);

  always @(posedge clk or posedge reset)
    begin : parCheck_1_process
      if (reset == 1'b1) begin
        parCheck_reg <= {2{1'b0}};
      end
      else begin
        if (enb) begin
          parCheck_reg[0] <= parCheckTmp;
          parCheck_reg[1] <= parCheck_reg[0];
        end
      end
    end

  assign parCheck = parCheck_reg[1];

  assign data_1 = data_2;

  assign valid_1 = valid_2;

endmodule  // DecoderCore

